  for (let idx = 0; idx < p.length; idx++) {
    const ch = p[idx];
    if (ch === '*') {
      if (el.length > 0 && el[el.length - 1][1] === false) el[el.length - 1][1] = true;
    } else {
      el.push([ch, false]);
    }
  }
  const m = el.length;
  function match(i, k) {
    if (k === m) return i === s.length;
    const c = el[k][0];
    const starred = el[k][1];
    if (!starred) {
      if (i < s.length && (c === '.' || c === s[i])) return match(i + 1, k + 1);
      return false;
    }
    if (match(i, k + 1)) return true;
    let j = i;
    while (j < s.length && (c === '.' || c === s[j])) {
      j++;
      if (match(j, k + 1)) return true;
    }
    return false;
  }
  return match(0, 0);
}

function solve(s, p) {
  const el = [];
  for (let idx = 0; idx < p.length; idx++) {
    const ch = p[idx];
    if (ch === '*') {
      if (el.length > 0 && el[el.length - 1][1] === false) el[el.length - 1][1] = true;
    } else {
      el.push([ch, false]);
    }
  }
  const n = s.length;
  const m = el.length;
  const dp = [];
  for (let i = 0; i <= n; i++) dp.push(new Array(m + 1).fill(false));
  dp[n][m] = true;
  for (let i = n; i >= 0; i--) {
    for (let k = m - 1; k >= 0; k--) {
      const c = el[k][0];
      const starred = el[k][1];
      const hit = i < n && (c === '.' || c === s[i]);
      if (!starred) {
        dp[i][k] = hit && dp[i + 1][k + 1];
      } else {
        dp[i][k] = dp[i][k + 1] || (hit && dp[i + 1][k]);
      }
    }
  }
  return dp[0][0];
}
